// Ported from the Node app's Sequelize model Room (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class RoomConfiguration : IEntityTypeConfiguration<Room>
{
    public void Configure(EntityTypeBuilder<Room> builder)
    {
        builder.ToTable("rooms", t =>
        {
            t.HasCheckConstraint("CK_rooms_kind", "[kind] IN (N'classroom', N'lab', N'hall', N'library', N'ground', N'other')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(80)").HasMaxLength(80).IsRequired();
        builder.Property(e => e.Kind).HasColumnName("kind").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'classroom'");
        builder.Property(e => e.Capacity).HasColumnName("capacity");
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
